import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷十一","description":"周易經傳集解 - 周易經傳集解卷十一","frontmatter":{"title":"周易經傳集解卷十一","description":"周易經傳集解 - 周易經傳集解卷十一"},"headers":[],"relativePath":"classics/jingchuan-jijie/012.md","filePath":"classics/jingchuan-jijie/012.md"}'),r={name:"classics/jingchuan-jijie/012.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷十一",tabindex:"-1"},[n("周易經傳集解卷十一 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷十一","aria-label":"Permalink to “周易經傳集解卷十一”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解噬嗑賁卷十一 ​宋林栗撰序卦曰：「可觀而後有所合，故受之以噬嗑」。「嗑」者，合也。「噬嗑」成卦，親之變也。自觀之「噬嗑」，「坤」變為「震」，「巽」變為「離」，四、五相變而成也。坤變為「震」，順而動也；巽變為「離」，入而麗也。順而不動，則無以明四夷之來王；入而不麗，則無以見群心之戴後。蓋觀之九五，有可觀之德，四方合而歸之，而強梗之徒於其間，噬而嗑之可也。故變初為九，與上相須，而主嗑之事。四五相易，不剛不柔，而成嗑之功。何則？九五在上，而六四在下，是以為可觀也。六五在上，而九四在下，是以為相合也。子曰：「為政以德，譬如北辰，居其所而眾星拱之。」詩云：「自西自東，自南自北，無思不服。」「噬嗑」，次觀之義也。「噬嗑」：亨，利用獄。彖曰：頤中有物，曰「噬嗑」。「噬嗑」而亨，剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，「利用獄」也。下震上離，成卦曰「噬嗑」者，初為「震」，二為「艮」，三為「坎」，四為「離」。震，動也；離，麗也；艮，止也；坎，陷也。動而麗，謂之合可矣，安得噬物之象乎？「噬」者，齧也。物止而陷於動麗之間，斯以為「噬嗑」而已矣。故子曰：「頤中有物，曰噬嗑。」「噬嗑」而「亨」，下動上止而中虛，頤之象也。六四變而為剛，頤中有物之象也。「頤中有物」，噬之則嗑，不噬則不嗑也。噬而嗑之，茲其所以「亨」歟？故曰：「易者，象也。」自王弼以來，擯象而言易者，讀至於此，不得不自疑其論之疏矣。夫天下之人，既已合而歸我，然而不免於「噬齧」雲者，豈復有干戈介冑之事哉？夏之訐俗，商之頑民，詰之以法，究之以情，茲噬齧之謂也。故曰「利用獄」。坎為刑獄故也。先王之用刑也，盡心於訊鞠之間，至於再，至於三，既服而後刑之。書曰「要囚」，伏念五六日，至於旬時，丕蔽要囚是也。然則不曰「利用刑人」，而曰「利用獄」，噬嗑之旨蓋可見矣。子曰：「剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，利用獄也。」在卦三陽三陰，剛柔分也。下震上離，動而明也。凡獄之道，一於剛則無以盡其情，一於柔則無以斷其罪。剛柔分，所以為利也。自臨與觀，皆二陽而四陰，至「噬嗑」而剛柔始分故也。明而不動，則威玩而不行。動而不明，則情遁而不得。動而明，所以為利也。雷電亦震「離」之物也。雷電不合，則威不章。柔得中而上行，離火之象也。火不上行，則其明不遠。凡卦言「柔得中」、「柔上行」，皆離火之象也。刑人於市，與眾棄之，如雷如火如電，不亦宜乎？六五為君，九四為臣，不當位也。文王罔攸兼於庶獄庶慎，惟有司之牧夫。故為君者，必以柔而濟乎剛；為臣者，必以剛而濟乎柔。士師曰殺之，三君曰宥之，三王三宥，然後制刑，於是乎情法兩得，威惠兼行，故曰「雖不當位，利用獄」也。易之取象，不一而足。「頤中有物」，一取象也。「剛柔分」，二取象也。「動而明」，三取象也。「雷電合」，四取象也；「柔得中而上行」，五取象也；「剛柔不當位」，六取象也。在他卦皆如此，非特如此也。繋辭曰：「日中為市，致天下之民，聚天下之貨，交易而退，各得其所，蓋取諸噬嗑。」離為日，震為市，上明而下動也。致天下之民，亦四方未合之義也。而或者得其一句一義，自以為盡之矣，不亦誣乎？象曰：「雷電」，「噬嗑」，先王以明罰勑法。「雷電」當作「電雷」，傳寫誤也。電者，「離」也。雷者，震也。雷電之至，當先電而後雷。故噬嗑以其序言之，而豐則曰「雷電皆至」也。亦猶「雲雷屯」，「雷雨作解」，「雷風恆」，「風雷益」之義也。先王觀此之象，雷電未嘗不起於細微，千里之行，未嘗不始於足下。麗也者，動之始也。初九者，閒之於初也。初而懲之，咎可無也。故子曰：「履校滅趾，不行也。」夫所為滅其趾者，非直苦之而已也。使知其過在於趾，尼而不行，何咎之有？故於繋辭又曰：「小人不恥不仁，不畏不義，不見利不動，不威不懲。小懲而大誡，此小人之福也。」是以為「無咎」也。或曰：古者象刑，中刑雜。履以菲䋽藨蒯為之，此之謂「履校」。考之文義，深恐不然。傳曰：「雖有絲麻，毋棄菅蒯。」菲䋽藨蒯以為刑人之履，無罪之人乃當徒跣而行耳，況於初九不應中刑之義，經又言「屨」、言「校」而不言「罪」乎？若加「校」以「履」，於義尤害矣。雜卦曰：「噬嗑，食也。」「噬嗑」與「頤」皆食也。「頤」為養而噬為食者，「頤」之口實不留於「頤」，而噬嗑之物皆堅韌而不可咽，方且咀嚼乎「頤」之間故也。是以「噬嗑」諸爻，皆取食物以為之義焉。初、上二爻有唇「頰」之象，故不言其所噬之物。中間四爻為所噬之物，有難易之殊也。六二「噬膚」，六三「臘肉」，九四「乾胏」，六五「乾肉」是也。噬之難易，備於四爻，故以初、上言用刑之始終。小人為惡，積微至著，小而不懲，必至於大咎也。初九：履校。上九「何校」是已。初九：屨校滅趾，無咎。象曰：「屨校滅趾」，不行也。初九，震也，以陽居剛，而在下卦之下，故曰「屨校滅趾」。震為足而居下，故有趾屨之象。其在「噬嗑」，故有滅趾之象。「滅」，沒也；「校」，械也。屨校者，明其為足械也。此罷民也。古者民之有罪而未麗於法者，桎梏而坐諸嘉石，役諸司空，使州里任之，然後宥而舍之。梏，手械；桎，足械也。言足則手可知矣。易之所謂「屨校」，周禮之所謂「桎」也。見械而不見足，是以謂之「滅趾」也，故曰「無咎」。小人之為惡，誠柔也。其在「噬嗑」，豈真柔物哉？柔而靱者也。此愚民也。訊其罪而不辨，加之刑而無辭，其勢易服，而其情難得也。吾不求其情而以剛治之，則其枉者不可勝言矣。後雖悔之，其可及乎？故治之者，不可不以柔道行之也。反覆訊鞫，研核其情，必得其服而後刑之。六二者，所以治六二也。如噬膚革柔靱之物，必細齧之，然後可嗑也，故曰「滅鼻」。「艮」為鼻，其在「噬嗑」，有滅鼻之象焉。「滅鼻」，劓也。五刑之厲，劓刵為輕。二為劓，則初為「刵」可知矣。三為斬左趾，四為斬右趾，五為宮刑，上剕滅耳，當為「刵」矣。曰：聖人之言，不可使易而知文。初為刑之始，上為刑之終，始為「剕」，終為「刵」，不已舛乎？是故「滅趾」、「滅耳」，皆系之以「屨校」、「何校」之辭，謂其校之沒之，非剕、刵之謂也。鼻既無校，非劓而何？故曰「無咎」。聖人以人命為重刑而未至於死，皆有悔過自新之路，是以系之「無咎」也。子曰：「噬膚滅鼻，乘剛也。」言六二居中，宜若無罪，罪在於乘剛歟？六二：噬膚滅鼻，無咎。象曰：「噬膚滅鼻」，乘剛也。六二，「艮」也，以陰居柔而在下卦之中，故曰「噬膚」。凡噬嗑中爻，皆言所噬之物有難易之殊，又即其爻便得噬之之義。「膚」，革也。「艮」為堅，故有膚革之象。舊說以膚為柔脆肥美之物，則失之矣。何則？膏粱芻豢以充口實，謂之「頤」可矣，惡用齧之為哉？刑獄之設，為強梗不服者設耳，柔良之民，惡用刑獄為哉？「剝」之六四曰：「剝床以膚。」謂皮膚也。鳥獸之革皆謂之「膚」，膚雖柔也，其實靱也。不噬而嗑，則咽骾而胃覆矣。六二以陰居柔，以明罰休雷以敕法。敕，正也。明罰以當其罪，敕法以致其威也。傳曰：「刑法威獄，以象天之震曜殺戮。」斯之謂矣。六三，噬臘肉，遇毒，小吝，無咎。象曰：「遇毒」，位不當也。六三上體為「坎」，下體為「艮」，以陰居剛而在下卦之上，故曰「噬臘肉」。小物全乾曰「臘」。「坎」為堅多心，「艮」為堅多節，「坎」又為隱伏，故有「臘肉」之象。「臘肉」者，肉見於外而骨藏於中，人之所不察也。以六居三，外柔而內剛，「臘肉」之謂矣，故曰「遇毒」。「毒」，猶害也。「噬臘肉」而遇骨，斯遇其害矣。徒信其外而不疑其中，是以謂之「遇」也。此奸民也，外示柔懦，而中藏險狠，以數誤我而匿其情者也。故治之者，不可不先柔而後剛也。柔以得其奸，剛以制其毒。六三者，所以治六三也。如噬乾臘藏毒之物，必揣其骨而徐齧之也，故曰：「小吝，無咎。」噬而遇毒，故有「小吝」；終能「嗑」之，故「無咎」也。子曰：遇毒，位不當也。人必自侮，然後人侮之。君子正身以正民，尚何遇毒之有哉？或曰：六三、上九，曷不以相應言其義乎？曰：以應而從，以類而聚，則不待噬而合矣。是以六位各隨本爻而取義焉。九四：噬乾胏，得金矢，利艱貞，吉。象曰：「利艱貞，吉」，未光也。九四上體為「離」，下體為「震」，以陽居柔，而在上卦之下，故曰「噬乾胏」。肉之附骨曰「胏」。震為剛，離為柔；震為出，離為麗，故有「乾胏」之象。乾胏者，骨見於外，而肉附其間，其強可見者也。以九居四，外剛而內柔，乾胏之謂矣。六爻中最為強梗難噬者，九四也。以全體觀，其象可見矣。此兇民也，其色悍然，其辭勃然，敢於犯上，而實無能為者也。治之不可不先剛而後柔也。剛以折其義，柔以原其情，故九四者，所以治九四也。如乾胏骨骾之物，必齧碎之，既柔而後可食也，故曰「得金矢」。金，剛也；矢，直也。震為金，離為矢，故有金矢之象。古之為訟者，使入束矢，以明求直也；為獄者，使入鉤金，以明求剛也。噬乾胏而嗑之，則得其剛直矣。得其剛直，斯得其金矢矣。故曰「利艱貞吉」。夫「噬嗑」之物，莫非堅靱，若柔脆易嗑，則無事於噬矣。然即其中而有最難者，得不以「艱」為「貞」乎？是故九四為乾胏，胏難於臘，臘難於膚，膚難於乾肉。故子曰：「利艱貞吉，未光也。」道之以政，齊之以刑，雖得金矢，豈足為光亨也哉？為其體乎震離，故以未光明之也。或曰：若是，則骨無堅脆，皆可噬而嗑之乎？曰：所為臘與胏者，凡以為口實也。苟非噬之所能噬，則去之久矣。夷狄之未臣，強籓之未服，而可以刑獄治之乎？詩不云乎：「人亦有言，柔則茹之，剛則吐之。」唯仲山甫柔亦不茹，剛亦不吐，「噬嗑」之謂也。柔如膚而不茹，剛如胏而不吐，聖人之意蓋可見矣。或問：「震為金，何也？」曰：乾以健，故為馬；以剛，故為金。三子者，得其剛健之餘，是故得而稱之也。屯之乘馬，蒙之金夫是已。知此者，其可與語易象乎？六五：噬乾肉，得黃金，貞厲，無咎。象曰：「貞厲無咎」，得當也。六五，「坎」也。以陰居剛而在上卦之中，故曰「噬乾肉」。「坎」為豕，為堅，故有「乾肉」之象。「乾肉」者，析骨披筋而暵之也。無膚與骨，特「乾肉」耳。似剛非剛，似柔非柔，噬之斯嗑，不噬則不可嗑也。以六居五，剛柔適中，「乾肉」之謂矣。或曰：六五外柔而內剛也，不曰臘肉，何哉？曰：三以坎而藏「艮」，五之象坎而已。五又得中，非三之比也。此庸常之民也，縱之則為惡，禁之則為非，頑嚚而不可訓，強悍而難令者也。治之者，不可不兼用乎柔剛也。寬以濟猛，猛以濟寬，不剛不柔，施得其當，民自服也。禮曰「刑平國用輕典」，書曰「列用中罰」是也。是故六五者，所以治六五也。如噬乾肉脯修之類，雖輕齧之，未有不噬者也，故曰「得黃金」。黃者，中也；金者，剛也。古之治刑者，疑則贖之。虞書：「金作贖刑。」孔安國曰：「金，黃金也。」周書：「百辟疑赦，其罰百鍰。」安國曰：「鍰，黃鐵也。」然則黃金之為贖，明矣。贖人而以黃金者，取其剛而不過也。噬乾肉而「嗑」之，則得其中。剛以得其中，斯得其黃金矣。夫豈以金矢黃金為利也哉？以明夫剛直剛中之道，如斯而已矣。故曰「貞厲，無咎」。為人上者，不能使民遷善遠罪，而嘗以噬嗑為正，雖刑得其當，猶未免於厲也。刑得其當，而猶以為厲，茲其所以無咎也歟！九四之「艱貞吉」，亦此意也。四言「吉」而五言「無咎」者，為君之道與臣下不同也。「噬嗑」諸爻皆有兩義，明為惡之人與用獄之利，故夫子之釋爻象，錯互而明之。初六曰「不行也」，六二曰「乘剛也」，上九曰「聰不明也」，皆為罪人言之也；六三曰「位不當也」，九四曰「未光也」，六五曰「得當也」，皆為用獄者言之也。學者可不深求其旨趣乎？上九：何校滅耳，兇。象曰：「何校滅耳」，聰不明也。上九，「離」也。以陽居柔而在上卦之上，故曰「何校滅耳」。「滅耳」則目可知矣。「坎」為耳，「離」為目，其在「噬嗑」，故有「滅耳」之象。「校」者，械也。「何」者，戴也。「何校」者，明其為首械也。古之制大辟者，使之何校而沒其耳目，謂其有目而無睹，有耳而無聞，不聰不明以至於此也。此頑嚚之民也，不可告語，不知話言，小懲而不懼，大誡而不悛者也。雖欲無㓙，其可得乎？故曰「兇」。子曰：「何校滅耳，聰不明也。」又曰：「善不積，不足以成名；惡不積，不足以滅身。小人以小善為無益而不為也，以小惡為無傷而不去也，故惡積而不可揜，罪大而不可解。」此之謂也。噬嗑之義，蓋本於君臣、父子、夫婦、兄弟、朋友之間，此五者，宜合者也。宜合而不合，則必有離間於其間者也。治而柔之，上下乃合，此噬嗑之義也。而說者皆以「噬膚」為柔美之物，則是柔良之民無罪而刑之也。甚者以為上下諸爻反覆相噬，故其論曰：「道德之衰，上下相噬，則教化不用，而刑為先。」嗚呼！何其悖哉！自黃帝、堯、舜以來，雖天下大亂，未有相噬如禽獸者也，而易乃教之，何哉？上下相噬，而吾又言「噬治」，是生民之類滅盡而後已也，其能使之合乎？記曰：「刑者形也；形者，成也。一成而不可變，故君子盡心焉。」聖人之於噬嗑，其所以教詔後世，明謹用刑，盡心於獄，不吐剛，不茹柔，寬猛相濟，期於無刑者，可謂深切著明矣。而學者爭以其私意汨之，以至於此，故不敢不辨。而孟子曰：邪說誣民，充塞仁義，仁義充塞，則率獸食人，人將相食。吾為此懼。閒先聖之道，距楊、墨，放淫辭，以承三聖者，豈好辨哉？予不得已也。愚於噬嗑則雲：序卦曰：嗑者，合也。物不可以苟合而已，故受之以賁。賁者，飾也。賁之成卦，噬嗑之反也。自噬之賁，三四相易，震、艮相推而成也。動而明所以為嗑，明以止所以為賁也。夫噬嗑與賁，皆為頤中有物之象，一為噬嗑，一為賁者，噬嗑得頤之下動，賁得頤之上止，動故為噬，止故為賁也。夫君臣不可以苟合也，必有朝廷之禮焉。父子不可以苟合也，必有閨門之禮焉。男女不可以苟合也，必有夫婦之禮焉。長幼不可以苟合也，必有鄉黨之禮焉。朋友不可以苟合也，必有儐相之禮焉。君以此始，亦以此終，以苟合者，必以苟離也。聖人重其合而畏其離，是故飾之以禮，使之粲然有文以相接，歡然有恩以相愛，則其合也必堅，而非一朝一夕之可離也。然則賁者，非徒為之文飾而已，將以固其合也。受之以賁，不其然歟？賁：亨，小利有攸往。彖曰：「賁，亨」，柔來而文剛，故亨。分剛上而文柔，故「小利有攸往」，天文也。文明以止，人文也。觀乎「天文」，以察時變；觀乎「人文」，以化成天下。下離上艮，成卦曰「賁」者，初為離，二為坎，三為震，四為艮，離為赤，坎為墨，震為青，艮為黃。夫「賁」之言文也。文也者，五色是也。「賁」有四象而無其白，何也？曰：白，金之色也。兌為白者，金盛於酉也。巽為白者，金生於巳也。金歸於醜，其在坎艮之間乎？是以上卦三爻，六四體乎艮坎，而有「皤如白馬之象。六五、上九皆得艮之一體，而有束帛白賁之辭也。然則五色者，四象具之矣。不言餘色，而三稱白者，所以發明之歟？或曰：乾為大赤，坤為大黑，而賁無其象，可謂備乎？」曰：乾坤者，天地也。天地也者，五行之所自生，五色之所自成。五色備，而天地之色在其中矣。離，南方也；坎，北方也。離坎也者，天地之中也。震，東方也；艮，西方也。震艮也者，天地之始終也。日月星辰，經緯於天，山川草木，森羅於地，是以謂之賁也。賁，亨，小利有攸往。何謂也？曰：賁之下卦為離，離，柔也，麗也。柔而麗者，不能以自亨也。今以相賁為義，則上卦之柔來文乎剛，其象為坎，是以亨也。上卦為艮，艮，止也，少也。少而止者，不能有所往也。今以相賁為義，則下卦之剛上而文柔，其象為震，是以「利有攸往」也。亨者，通也。往者，行也。坎為通，震為行故也。故子曰：「柔來而文剛，故亨。」明離之不能亨，亨者，坎也。分剛上而文柔，故小利有攸往，明艮之不能往，往者震也。先儒不究厥旨，乃謂泰變為賁，故有柔來剛上之義。近世易家病其無據，乃取而圖之，由泰否而變者十有八，由復姤而變者十，由臨遁而變者二十有八。甚哉，其謬也。愚嘗著論以闢其失，茲列其梗槩耳。夫子既釋彖辭，又總而言之曰：「天文也。文明以止，人文也。」蓋以四象言之，則天文粲然矣；以二象言之，則人文煥然矣。言天而及地者，在天成象，在地成形，形質流於地，而文采彰乎天，言天而地可知矣。是故日月之明，離坎之象，五星錯緯，五行之象，此則所謂粲然者也。日中星鳥以殷仲春，日永星火以正仲夏，宵中星虛以殷仲秋，日短星昴以正仲冬，故曰「觀乎天文，以察時變」也。至於「文明以止」，則專取「離」「艮」以明人事。非明無以燭天下之幽，非止無以制天下之動。文成不亂謂之明，位定不爭謂之止，此則所謂煥然者也。父子有親，君臣有義，夫婦有別，長幼有序，貴有常尊，賤有等威，上不伏下，下不僭上，故曰：「觀乎人文，以化成天下也。」「賁」之六位，一剛一柔，一動一靜。「坎」「離」天地之中，「艮」「震」天地之終始。「離」明而「坎」幽，「艮」上而震動，陰陽迭用，質文交錯，而三才之義備矣。象曰：山下有火，「賁」，君子以明庶政，無敢折獄。「山」者，「艮」也。「火」者，「離」也。「山上有火」，則散而燎原，是以為「旅」也。「山下有火」，則止而有耀，是以為「賁」也。山有草木，火炎其下，光華燦爛，而成五采之文，「賁」之象也。「君子以明庶政，謹庶獄」，亦猶是爾。「明庶政」則取諸「離」；「無敢折獄」，則取諸「艮」也。「敢」，讀如老子「勇於敢」之「敢」。「獄」者，人命所繋，情偽萬端，其可任一己之聰明，而以果敢折之哉？山上有火，其明著矣，獄之不留，固其宜也。山下有火，其明未著，無敢於折，不亦宜乎？雜卦曰：「賁，無色也。」「賁」之為卦，以剛柔相賁而成。其在六爻，以雜然成文為義。夫賁也者，五色皆具，而曰「賁無色」，何也？曰：非無色也，無定色也。周禮曰：青與赤謂之文，赤與白，謂之章，白與黑謂之黼，黑與青，謂之黻。五采備謂之繡矣。赤與黑，青與白，玄與黃，獨不為賁乎？是之謂無色也。是故「賁」之六爻，或以相應而成文，或以相附而成文，或以相合而成文。初九、六四，相應而成文也。六二、九三，相附而成文也。六五、上九，相合而成文也。相應之文，組織是也。相附之文，繡繪是也。相合之文，紐綴是也。或曰：六五、上九，不亦相附而成乎？曰：六二，純柔也，不附於剛，則不能以成文。九三，純剛也，不附於柔，則不能以成文。至於六五以柔居剛，上九以剛居柔，既已成文矣，而皆無其應，得非相合以成者乎？是故六二「坎」也，九三「離」也，一陷一麗，有相附之義也。六五「艮」也，上九「震」也，一動一止，有相合之義也。或曰：初九、六四亦離、坎也，不曰相附，何哉？曰：離之與坎，近則相附，遠則相應，不其然乎？不其然歟？初九：賁其趾，舍車而徒。象曰：「舍車而徒」，義弗乘也。初九，「離」也，以陽居剛，而在一卦之下，應乎六四之「坎」，故曰：「賁其趾。」初九與六四相賁者也，下卦之下，趾之象也，故曰「舍車而徒」。初近於二而配於四，二四皆「坎」也。「坎」為車，而四有「艮」體。「艮」，止也。六四之車止於上，而六二之車當其前，舍二而從四，不得不徒行矣。以剛明之才而居最下之地，安於徒行者也。夫乘車，安也；徒行，勞也。初九遇六二之車，斯可乘矣。可乘而不乘者，以為物不可以苟合也。吾之所應者，四也，其可遇二之車而遂乘之歟？夫所為舍車者，將以賁其趾也。苟為義不當乘而乘之，則夫「賁」者，秪所以為趾歟？是故君子寧舍車而徒行，不見利而忘義，乃所以賁其趾也。故子曰：「舍車而徒，義弗乘也。」夫豈終於徒行而已哉？六四之「馬翰如」矣。六二：賁其須。象曰：「賁其須」，與上興也。六二，「坎」也，以陰居柔而在下卦之中，上無其應而承九三之「離」，故曰「賁其須」。「須」，血之餘也。「坎」為血，故有「須」象。六二與九三相賁者也。上間於三，有須附頤之象也。「須」也者，所以賁其頤也。傳曰：「皮之不存，毛將安傅？」無九三之質，則六二之文無所施矣。虎豹之鞟，猶犬羊之鞟；無六二之文，則九三之質亦奚為矣？故曰：「君子義以為質，禮以行之，文質彬彬，然後君子。」子曰：「賁其須，與上興也。」「須」附於「頤」，隨上而興，六二、九三之象矣。九三：賁如，濡如，永貞吉。象曰：「永貞」之「吉」，終莫之陵也。九三下體為「離」，上體為「震」，以陽居剛而在下卦之上，上無其應，而介於二四之間，故曰「賁如濡如」。九三與六二相賁者也，而承於六四，為四所濡。四，「坎」也，「坎」為水，故有「濡如」之象。今有繒帛於此，既有其質，又有其文，或者濡之而不為染汙者，希矣。夫子有言：「不曰白乎？涅而不緇。」故曰：「永貞吉」。三既受「賁」於二，唯當永守其上，不染於四，斯為吉矣。凡「賁」之象，曰「明與止」。文成不亂謂之「明」，位定不爭謂之「止」。初應於四，三附於二，然後文成而不亂矣。初不乘二之車，三不受四之濡，然後定位而不爭矣。故子曰：「永貞之言，終莫之陵也。」「陵」，憑陵也。自上陵下，指六四也。六四：賁如，皤如，白馬翰如，匪寇婚媾。象曰：六四當位，疑也。「匪寇婚媾」，終無尤也。六四下體為「坎」，上體為「艮」，以陰居柔而在上卦之下，應乎初九之「乾」，故曰：「賁如，皤如。」皤，猶白也。「坎」、「艮」之間，其位在醜。醜，金之所歸，其色白，故有「皤如」之象。六四與初九相賁者也，物相雜，故曰「文」，未有一色而成文者也。今曰「賁如」，又曰「皤如」，何謂也？曰：六四體是艮止，隔於二爻，未遇其配，雖與初九有「賁如」之象，而「皤如」之質猶在也，故曰「白馬翰如」。「坎」、「艮」皆馬也，謂之「白馬」，猶「皤如」之義也。「翰」，鳥翼也。馬以足而言。「翰」者，謂其從初之志，如鳥之將翰飛也，故曰：「匪寇婚媾」。初近於二，二體「坎」，「坎」為「盜」，故有「寇」象焉。二與三相賁，非為寇者也。二三合，則四與初為「媾」矣。故子曰：「六四當位，疑也。匪寇婚媾，終無尤也。」九三、六四皆當其位，故其去就不能無疑。然終與初合，則可以無尤矣。聖人之為「賁」也，所以飾天下之物，不可以苟合也。「賁」之道行，而君臣、父子、夫婦各安其分。分安而保其合，爭鬥不興，禍亂不作。故六二與上同，而九三「濡如永貞」，則「終莫之陵」也。初九「舍車而徒」，而六四與之「婚媾」，則「終無尤也」，不既明甚矣乎？六五：賁於邱園，束帛戔戔。吝，終吉。象曰：六五之「吉」，有喜也。六五，「艮」也。以陰居剛而在上卦之中，下無其應，而承上九之「震」，故曰「賁於邱園」。六五與上九相賁者也。上九，「艮」之極，反而「震」者也。「艮」為山，故有邱園之象。邱園者，賢人君子遁藏之所在也。「艮」反而成「震」，始隱而終見矣，故曰：「束帛戔戔」。「束帛」者，聘賢之物；「戔戔」者，鮮少之貌。賢者不可以虛拘，不可以貨取，是故「束帛」以將其誠，「戔戔」以表其潔也。故曰：「吝，終吉。」夫宗廟之禮，朝廷之儀，賁之盛也。不施於此而於邱園，其為「賁」也，可謂「吝」矣。繡錦纂組，黼黻文章，「賁」之盛也。不施於此而施於束帛，其為「賁」也，可謂「吝」矣。然而「終吉」者，有得賢之喜也。得賢則能為邦家立太平之基矣，不亦吉乎？五在一卦之中，故有「終吉」之象。子曰：「六五之吉，有喜也。」伊尹耕於有莘之野，湯三使人以幣聘之，用能致君於堯舜之隆，其斯以為喜乎？上九：白賁，無咎。象曰：「白賁無咎」，上得志也。上九，「震」也。以陽居柔，而在上卦之上，乘六五之「艮」，故曰「白賁，無咎」。上九與六五相賁者也。六居五而九在上，屈己尊賢之義也。記曰：「甘受和，白受採。」詩曰：「素以為絢兮。」子曰：「繪事後素。」皆謂無其質者，不可有其文也。今六五、上九，皆文質彬彬，相合以成賁者也。時止則止，時行則行，動靜不失其宜，是以為無咎也。世之君子，德非純白，而託於邱園以蒙賁飾者，蓋有之矣。求譽而毀至，希寵而辱來，能無咎者，亦已鮮矣，樊英、李渤之流是也。如伊尹、太公望、四皓、諸葛孔明，隱居以求其志，行義以達其道，然後議者無所容其喙。故子曰：「白賁無咎，上得志也。」上九得行其志，見於有為，斯為無咎矣。周易經傳集解卷十一。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
